import axios from 'axios';

const client = axios.create();

const setToken = (token) => {
  if (token) {
    client.defaults.headers.common['x-auth-token'] = token;
  } else {
    delete client.defaults.headers.common['x-auth-token'];
  }
};

export const api = {
  setToken,
  auth: {
    login: (email, password) => client.post('/api/auth/login', { email, password }),
    register: (username, email, password) => client.post('/api/auth/register', { username, email, password })
  },
  stats: {
    get: () => client.get('/api/stats'),
    update: (payload) => client.put('/api/stats', payload)
  },
  newsletter: {
    subscribe: (email) => client.post('/api/newsletter', { email })
  },
  tools: {
    get: () => client.get('/api/tools'),
    create: (payload) => client.post('/api/tools', payload),
    remove: (id) => client.delete(`/api/tools/${id}`)
  },
  cases: {
    get: () => client.get('/api/cases')
  },
  settings: {
    get: () => client.get('/api/settings'),
    update: (payload) => client.put('/api/settings', payload)
  },
  contact: {
    submit: (payload) => client.post('/api/contact', payload)
  }
};
